<template><main class="page-shell min-h-screen p-6 text-white"><section class="surface mx-auto max-w-xl rounded-3xl p-6 text-center"><h1 class="text-3xl font-bold text-orange">ตั๋ว MovieHub</h1><p v-if="error" class="mt-4 text-rose-300">{{ error }}</p><template v-if="record"><img :src="qr" alt="Ticket QR" class="mx-auto my-6 h-56 w-56 rounded bg-white p-2"/><h2 class="text-xl font-bold">{{ record.booking.movieTitleSnapshot }}</h2><p class="mt-2">{{ record.booking.cinemaNameSnapshot }} · {{ new Date(record.booking.showtime.startsAt).toLocaleString('th-TH') }}</p><p class="mt-2">ที่นั่ง {{ record.booking.seats.map(s=>s.seatLabelSnapshot).join(', ') }}</p><p class="mt-4 text-sm text-slate-400">แสดง QR นี้ที่ทางเข้า · สถานะ {{ record.ticket.status }}</p></template><router-link to="/history" class="primary-button mt-6 inline-block">ไปประวัติการจอง</router-link></section></main></template>
<script setup>
import{ref,onMounted}from"vue";import{useRoute,useRouter}from"vue-router";import axios from"axios";import QRCode from"qrcode";
const route=useRoute(),router=useRouter(),record=ref(null),qr=ref(""),error=ref("");
onMounted(async()=>{if(!route.query.bookingId){router.replace('/');return;}try{const {data}=await axios.get(`/tickets/booking/${route.query.bookingId}`);record.value=data.data;qr.value=await QRCode.toDataURL(data.data.qrPayload,{errorCorrectionLevel:'M',margin:1,width:360});}catch(e){error.value=e.response?.data?.error?.message||"ยังไม่พบตั๋วที่ยืนยันแล้ว";}});
</script>
